1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { listBackups } from "./proxmox";
7	import { serverRootPassword } from "./sftp";
8	import { GAME_FAMILIES, type GameFamily } from "./games";
9	
10	/**
11	 * Server-ops actions: game-server auto-update toggle + "update now", and
12	 * self-service backup restore. Every action re-verifies ownership.
13	 */
14	
15	async function ownedServer(serverId: string) {
16	  const user = await requireUser();
17	  const server = await db.server.findUnique({
18	    where: { id: serverId },
19	    include: { osTemplate: true },
20	  });
21	  if (!server) throw new Error("Not found");
22	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
23	  return { user, server };
24	}
25	
26	/** Is this server's image a managed game family? */
27	function isGameServer(server: { osTemplate: { family: string } }): boolean {
28	  return GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
29	}
30	
31	/** Reject if another job is already queued/running on this server. */
32	async function ensureIdle(serverId: string): Promise<{ error?: string }> {
33	  const pending = await db.job.count({
34	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
35	  });
36	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
37	  return {};
38	}
39	
40	// ---------- Game-server auto-update ----------
41	
42	/**
43	 * Toggle `Server.autoUpdate` for a game server. Read-only for non-game images
44	 * (returns an error). The periodic worker sweep uses this flag.
45	 */
46	export async function toggleAutoUpdate(
47	  serverId: string,
48	  enabled: boolean
49	): Promise<{ error?: string; autoUpdate?: boolean }> {
50	  const { user, server } = await ownedServer(serverId);
51	  if (!isGameServer(server)) return { error: "Auto-update is only available for game servers." };
52	
53	  await db.server.update({ where: { id: server.id }, data: { autoUpdate: enabled } });
54	  await db.auditLog.create({
55	    data: {
56	      userId: user.id,
57	      action: "server.auto_update_toggle",
58	      detail: `${serverId} -> ${enabled ? "on" : "off"}`,
59	    },
60	  });
61	  revalidatePath(`/dashboard/servers/${serverId}`);
62	  return { autoUpdate: enabled };
63	}
64	
65	/**
66	 * Enqueue a one-off GAME_UPDATE job. The worker SSHes the per-family update
67	 * command over the private network, so the VM must be running.
68	 */
69	export async function triggerGameUpdate(serverId: string): Promise<{ error?: string }> {
70	  const { user, server } = await ownedServer(serverId);
71	  if (!isGameServer(server)) return { error: "Updates are only available for game servers." };
72	  if (server.status !== "RUNNING") {
73	    return { error: "Server must be running to apply a game update." };
74	  }
75	  if (!server.ipAddress || !serverRootPassword(server)) {
76	    return { error: "Server is still provisioning — try again shortly." };
77	  }
78	  const idle = await ensureIdle(serverId);
79	  if (idle.error) return idle;
80	
81	  await db.job.create({ data: { type: "GAME_UPDATE", serverId } });
82	  await db.auditLog.create({
83	    data: { userId: user.id, action: "server.game_update", detail: serverId },
84	  });
85	  revalidatePath(`/dashboard/servers/${serverId}`);
86	  return {};
87	}
88	
89	// ---------- Self-service backup restore ----------
90	
91	export type ServerBackup = { volid: string; ctime?: number; size?: number };
92	
93	/**
94	 * List the vzdump backups on the `backup` storage that belong to this server's
95	 * VMID. Read-only Proxmox call, ownership-checked.
96	 */
97	export async function listServerBackups(
98	  serverId: string
99	): Promise<{ error?: string; backups?: ServerBackup[] }> {
100	  const { server } = await ownedServer(serverId);
101	  if (!server.vmid) return { backups: [] };
102	  try {
103	    const backups = (await listBackups(server.vmid)) as ServerBackup[];
104	    backups.sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
105	    return { backups };
106	  } catch {
107	    return { error: "Could not reach the hypervisor — try again in a moment." };
108	  }
109	}
110	
111	/**
112	 * Enqueue a BACKUP_RESTORE job for the selected vzdump archive. This OVERWRITES
113	 * the server's current disk. The volid is validated against the server's own
114	 * backups so a customer can only restore their own VM's archives.
115	 */
116	export async function requestRestore(
117	  serverId: string,
118	  volid: string
119	): Promise<{ error?: string }> {
120	  const { user, server } = await ownedServer(serverId);
121	  if (!server.vmid) return { error: "Server has no VM yet." };
122	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
123	    return { error: "Server must be running or stopped to restore a backup." };
124	  }
125	
126	  // Validate the archive actually belongs to this server's VMID (prevents
127	  // restoring another customer's backup by guessing a volid).
128	  let owned: ServerBackup[];
129	  try {
130	    owned = (await listBackups(server.vmid)) as ServerBackup[];
131	  } catch {
132	    return { error: "Could not verify the backup — the hypervisor is briefly unavailable." };
133	  }
134	  if (!owned.some((b) => b.volid === volid)) {
135	    return { error: "That backup was not found for this server." };
136	  }
137	
138	  // DATA SAFETY (critical): `qmrestore --force` over an existing VM calls PVE's
139	  // destroy_vm first ("avoid zombie disks when restoring over an existing VM"),
140	  // and destroy_vm frees EVERY volume the vmid owns, `unusedN` entries included.
141	  // Restoring a backup taken before a volume was attached therefore destroys that
142	  // volume's data silently, while `Volume.diskName` keeps pointing at the dead
143	  // volid and billing carries on.
144	  //
145	  // Reinstall already refuses for exactly this reason. Restore does the same thing
146	  // to the same vmid and had no guard at all — same rule, both layers.
147	  const pinnedVolumes = await db.volume.count({ where: { serverId } });
148	  if (pinnedVolumes > 0) {
149	    return {
150	      error:
151	        `Restoring replaces this server's disks, which would also destroy the ` +
152	        `${pinnedVolumes} data volume${pinnedVolumes === 1 ? "" : "s"} assigned to it — ` +
153	        `including any you have detached. Move or delete them first, then restore.`,
154	    };
155	  }
156	
157	  const idle = await ensureIdle(serverId);
158	  if (idle.error) return idle;
159	
160	  await db.job.create({ data: { type: "BACKUP_RESTORE", serverId, payload: { volid } } });
161	  await db.auditLog.create({
162	    data: { userId: user.id, action: "server.backup_restore", detail: `${serverId} ${volid}` },
163	  });
164	  revalidatePath(`/dashboard/servers/${serverId}`);
165	  return {};
166	}
