131	// ---------------------------------------------------------------------------
132	// Scheduling
133	// ---------------------------------------------------------------------------
134	
135	/**
136	 * Is another automatic backup due?
137	 *
138	 * Anchored on the last ATTEMPT, never on the last SUCCESS. Anchoring on success
139	 * looks more correct and is a trap: a server whose backups always fail has no
140	 * success to anchor to, so it would be "due" on every 15-minute sweep pass
141	 * forever — hammering a sick VM and burying the rest of the fleet's queue behind
142	 * it. The attempt is a fact; the outcome is what we refuse to assume.
143	 */
144	export function isAutoBackupDue(opts: {
145	  now: number;
146	  intervalHours: number | null;
147	  lastAttemptAt: Date | null;
148	}): boolean {
149	  const hours = opts.intervalHours ?? 0;
150	  if (!(hours > 0)) return false;
151	  if (!opts.lastAttemptAt) return true;
152	  return opts.now >= opts.lastAttemptAt.getTime() + hours * 60 * 60_000;
153	}
154	
155	export type BackupHealthState = "off" | "ok" | "pending" | "never" | "stale" | "failing";
156	export type BackupHealth = { state: BackupHealthState; detail: string };
157	
158	/** How many intervals may elapse with no verified backup before we call it stale. */
159	export const STALE_INTERVAL_MULTIPLE = 2;
160	
161	function stamp(d: Date): string {
162	  return d.toISOString().slice(0, 16).replace("T", " ") + " UTC";
163	}
164	
165	/**
166	 * The one sentence the customer reads under "Scheduled backups", and the same
167	 * one the sweep logs for the operator. It must never imply a restore point that
168	 * was not proved.
169	 *
170	 * `lastVerifiedAt` is `Server.lastAutoBackup`, which since H4 means "an archive
171	 * was observed in storage at this time" — not "a job was queued at this time".
172	 */
173	export function backupScheduleHealth(opts: {
174	  now: number;
175	  autoBackup: boolean;
176	  intervalHours: number | null;
177	  lastVerifiedAt: Date | null;
178	  lastAttempt: { at: Date; status: string } | null;
179	}): BackupHealth {
180	  const hours = opts.intervalHours ?? 0;
181	  if (!opts.autoBackup || !(hours > 0)) {
182	    return { state: "off", detail: "Scheduled backups are off for this server." };
183	  }
184	
185	  const verified = opts.lastVerifiedAt;
186	  const verifiedLine = verified
187	    ? `The most recent backup we can prove exists is from ${stamp(verified)}.`
188	    : "No automatic backup has ever been verified for this server, so the schedule has produced no restore point.";
189	
190	  // Ordered by what the customer stands to lose, not by tidiness: a failing
191	  // schedule outranks a stale one, which outranks "we have never seen one".
192	  if (opts.lastAttempt?.status === "FAILED") {
193	    return {
194	      state: "failing",
195	      detail:
196	        `The last automatic backup attempt (${stamp(opts.lastAttempt.at)}) FAILED. ` +
197	        `${verifiedLine} Open a ticket if this repeats — do not assume tonight's run will fix it.`,
198	    };
199	  }
200	
201	  if (!verified) {
202	    if (!opts.lastAttempt) {
203	      return {
204	        state: "pending",
205	        detail: "No automatic backup has run yet — the first one is queued by the next sweep.",
206	      };
207	    }
208	    return {
209	      state: "never",
210	      detail:
211	        `Automatic backups have been attempted since ${stamp(opts.lastAttempt.at)}, but none has ` +
212	        "been verified to exist in storage. Do not rely on having a restore point.",
213	    };
214	  }
215	
216	  const overdueAfter = verified.getTime() + hours * 60 * 60_000 * STALE_INTERVAL_MULTIPLE;
217	  if (opts.now > overdueAfter) {
218	    return {
219	      state: "stale",
220	      detail:
221	        `${verifiedLine} That is more than ${STALE_INTERVAL_MULTIPLE} backup intervals ago, so the ` +
222	        "schedule is not keeping up. Treat anything newer than that as unprotected.",
223	    };
224	  }
225	
226	  return { state: "ok", detail: `Last verified backup: ${stamp(verified)} (confirmed present in storage).` };
227	}
