268	// ---------------------------------------------------------------------------
269	// VM lifecycle: destroying a VM that may or may not still be there
270	// ---------------------------------------------------------------------------
271	
272	/**
273	 * Is this Proxmox error specifically "vmid <n> is not on this node"?
274	 *
275	 * PVE answers a GET/DELETE for an unknown vmid with HTTP 500 and the body
276	 *   Configuration file 'nodes/<node>/qemu-server/<vmid>.conf' does not exist
277	 * (verified by running `qm config 999123` on this host, 2026-07-27).
278	 *
279	 * The match is deliberately ANCHORED ON THE VMID rather than on the bare phrase
280	 * "does not exist". `remove()` in worker/index.ts used to swallow anything whose
281	 * message contained that phrase, which also matches errors that mean the exact
282	 * opposite of "the VM is gone" — `storage 'vmdata' does not exist`, `volume ...
283	 * does not exist`, `snapshot 'x' does not exist`. Any of those would have let the
284	 * DELETE handler decide the VM had been destroyed, drop the Server row and every
285	 * Volume row pinned to it, and leave a live VM running on the hypervisor with no
286	 * database record: unbilled, unmanageable and still holding customer data.
287	 */
288	export function isVmAbsentError(e: unknown, vmid: number): boolean {
289	  const err = e as { body?: unknown; message?: unknown } | null | undefined;
290	  const msg = `${err?.body ?? ""} ${err?.message ?? (typeof e === "string" ? e : "")}`;
291	  if (!Number.isInteger(vmid)) return false;
292	  return (
293	    new RegExp(`qemu-server[/\\\\]${vmid}\\.conf'?\\s+does not exist`, "i").test(msg) ||
294	    new RegExp(`\\bVM\\s+${vmid}\\s+does not exist\\b`, "i").test(msg) ||
295	    new RegExp(`\\bno such vm\\b.*\\b${vmid}\\b`, "i").test(msg)
296	  );
297	}
298	
299	/**
300	 * The side-effectful half of a VM teardown, behind a seam so the decision ladder
301	 * in `destroyVmIdempotent` can be exercised without a hypervisor.
302	 * `test/vm-lifecycle.test.ts` drives it with an in-memory fake.
303	 */
304	export type VmDestroyHost = {
305	  /** Ground truth from the hypervisor. "unknown" when it could not be read — never a guess. */
306	  probe: (vmid: number) => Promise<"present" | "absent" | "unknown">;
307	  /** Best-effort stop; may reject if the VM is already stopped or gone. */
308	  stop: (vmid: number) => Promise<void>;
309	  /** The destructive call. */
310	  destroy: (vmid: number) => Promise<void>;
311	};
312	
313	export type DestroyOutcome = {
314	  /** True when THIS call issued the destroy and the VM is verified gone afterwards. */
315	  destroyed: boolean;
316	  /** True when the VM was already absent, so no destructive call was issued. */
317	  alreadyAbsent: boolean;
318	  detail: string;
319	};
320	
321	/**
322	 * Destroy a VM in a way that is SAFE TO RUN TWICE, and that never claims a
323	 * teardown it did not observe.
324	 *
325	 * INCIDENT (found in audit, 2026-07-27 — worker/index.ts `reinstall`): REINSTALL
326	 * is destroy-then-provision, and the worker retries a failed job up to
327	 * MAX_ATTEMPTS times. `destroyVm` issued `DELETE /qemu/<vmid>` unconditionally
328	 * and did not tolerate the VM already being gone. So when attempt 1 destroyed the
329	 * VM and then failed anywhere in the re-provision that follows (a snippet write,
330	 * a clone timeout, a config POST), attempts 2 and 3 both died on the very first
331	 * step — `Configuration file '…/<vmid>.conf' does not exist` — and never reached
332	 * the provision that was supposed to rebuild the machine. The job ended FAILED,
333	 * REINSTALL is in VM_STATE_FAILURE_JOBS so the server was flipped to ERROR, and
334	 * the customer was left with no VM at all: the retry mechanism itself converted a
335	 * recoverable mid-reinstall failure into permanent destruction. `remove()` in the
336	 * same file already tolerated the absent case, which is what made the omission
337	 * here an oversight rather than a policy.
338	 *
339	 * The ladder:
340	 *   1. PROBE FIRST. An absent VM means there is nothing to destroy — return
341	 *      without issuing any destructive call at all.
342	 *   2. "unknown" does NOT block the destroy (the caller has already decided this
343	 *      vmid is to be torn down, and the vmid is not in question), but it is
344	 *      carried into the detail so nothing downstream reads it as a clean run.
345	 *   3. TOLERATE a vmid-anchored absent error from the destroy itself — that is
346	 *      the retry racing a previous attempt that actually succeeded.
347	 *   4. VERIFY AFTER. Re-probe; if the VM is still present the destroy did not
348	 *      happen and we throw, rather than let a caller delete the database rows
349	 *      that are the only remaining handle on a live machine.
350	 */
351	export async function destroyVmIdempotent(
352	  host: VmDestroyHost,
353	  vmid: number
354	): Promise<DestroyOutcome> {
355	  const beforeState = await host.probe(vmid);
356	  if (beforeState === "absent") {
357	    return {
358	      destroyed: false,
359	      alreadyAbsent: true,
360	      detail: `VM ${vmid} was already absent — no destroy was issued`,
361	    };
362	  }
363	
364	  // Stop first. A stop failure is not fatal: the VM may already be stopped, and a
365	  // real blocker (a config lock, a running backup) will surface on the destroy.
366	  try {
367	    await host.stop(vmid);
368	  } catch {
369	    /* already stopped, or gone — the destroy below is the authority */
370	  }
371	
372	  try {
373	    await host.destroy(vmid);
374	  } catch (e) {
375	    if (!isVmAbsentError(e, vmid)) throw e;
376	    return {
377	      destroyed: false,
378	      alreadyAbsent: true,
379	      detail: `VM ${vmid} disappeared before the destroy landed — treating as already torn down`,
380	    };
381	  }
382	
383	  // Never report a teardown we did not observe.
384	  const afterState = await host.probe(vmid);
385	  if (afterState === "present") {
386	    throw new Error(
387	      `destroy of VM ${vmid} reported success but the VM is still present on the hypervisor — ` +
388	        `refusing to continue, because the caller would delete the only records that still point at it.`
389	    );
390	  }
391	  return {
392	    destroyed: true,
393	    alreadyAbsent: false,
394	    detail:
395	      afterState === "absent"
396	        ? `VM ${vmid} destroyed and verified gone`
397	        : `VM ${vmid} destroy completed, but its post-destroy state could not be read back`,
398	  };
399	}
