401	// ---------------------------------------------------------------------------
402	// VMID reuse: the previous tenant's backups
403	// ---------------------------------------------------------------------------
404	
405	/**
406	 * Choose a vmid for a NEW server, skipping any id whose backup archives are
407	 * still sitting in the shared `backup` storage.
408	 *
409	 * INCIDENT (found in audit, 2026-07-27): nothing ever removed a destroyed
410	 * server's vzdump archives. `remove()` purges the VM and deletes the Server row,
411	 * but `backup:backup/vzdump-qemu-<vmid>-*.vma.zst` survives indefinitely. PVE's
412	 * `/cluster/nextid` hands out the LOWEST free id, so the next server deployed
413	 * after a deletion lands on the freed vmid — and every surface that reasons about
414	 * backups keys on the vmid alone:
415	 *
416	 *   - `listBackups(vmid)` (this file) filters on `b.vmid === vmid`, so the new
417	 *     owner's Backups tab lists the previous tenant's archives as their own;
418	 *   - `requestRestore` in lib/actions-server-ops.ts validates the requested volid
419	 *     against that same listing, so it ACCEPTS them — one click restores a
420	 *     stranger's entire root filesystem onto the new customer's VM, handing them
421	 *     that tenant's databases, application secrets, SSH keys and /etc/shadow;
422	 *   - `pruneBackups` (this file) then counts those archives as the new owner's
423	 *     and DELETES the previous tenant's data to enforce keep-last-2.
424	 *
425	 * Live on this host today (read-only `pvesm list backup`, 2026-07-27): vmids
426	 * 100–104 and 8000 all hold archives while `/cluster/nextid` answers 105 — so a
427	 * single delete followed by a single deploy is all it takes.
428	 *
429	 * This is the NON-DESTRUCTIVE half of the fix: skip the id, delete nothing.
430	 * Deciding whether a terminated customer's archives should be reaped (and after
431	 * how long) is a data-retention policy call, not an audit call.
432	 *
433	 * Pure and total: no I/O, no clock. `candidate` is the hypervisor's suggestion,
434	 * `takenVmids` the ids already in use, `archivedVmids` the ids that still own
435	 * archives. Returns the first id at or above `candidate` that is in neither set.
436	 */
437	export function pickProvisionVmid(opts: {
438	  candidate: number;
439	  takenVmids: ReadonlySet<number>;
440	  archivedVmids: ReadonlySet<number>;
441	  maxProbe?: number;
442	}): { vmid: number; skipped: number[] } {
443	  const { candidate, takenVmids, archivedVmids } = opts;
444	  const maxProbe = opts.maxProbe ?? 512;
445	  if (!Number.isInteger(candidate) || candidate <= 0) {
446	    throw new Error(`pickProvisionVmid: '${candidate}' is not a usable vmid`);
447	  }
448	  const skipped: number[] = [];
449	  for (let id = candidate; id < candidate + maxProbe; id++) {
450	    if (takenVmids.has(id) || archivedVmids.has(id)) {
451	      skipped.push(id);
452	      continue;
453	    }
454	    return { vmid: id, skipped };
455	  }
456	  throw new Error(
457	    `no vmid free of stale backup archives in [${candidate}, ${candidate + maxProbe}). ` +
458	      `Reap the orphaned archives in the "backup" storage (pvesm list backup) before deploying — ` +
459	      `reusing one of these ids would show the new customer the previous tenant's backups.`
460	  );
461	}
