645	// ---------------------------------------------------------------------------
646	// Platform backups vs customer backups
647	// ---------------------------------------------------------------------------
648	//
649	// DATA LOSS PREVENTED (real, on this host, 2026-07-26): `scripts/backup-vms.sh`
650	// used to write the platform's own host-level disaster-recovery archives into the
651	// SAME Proxmox storage (`backup` -> /tank/backup/dump) that customers' on-demand
652	// backups land in, and `pruneBackups` below selected victims with nothing but
653	// `b.vmid === vmid`. So vmid 102 ended the 04:31 platform run holding two
654	// archives — the customer's own manual one from 2026-07-25 12:22 and the
655	// platform's 10 GB DR copy from 2026-07-26 04:31 — and the customer's very next
656	// click on "Create backup" (keep = CUSTOMER_BACKUP_KEEP = 2) would have deleted
657	// the platform's copy of their VM. Repeated across the fleet that silently
658	// destroys the entire bare-metal recovery set, one customer click at a time.
659	//
660	// The fix is three independent layers, in order of strength:
661	//
662	//  1. STRUCTURAL. `scripts/backup-vms.sh` now writes with `vzdump --dumpdir
663	//     /tank/backup/platform`, a directory that is NOT the `dump/` subdirectory of
664	//     any configured PVE storage. Proxmox only indexes `<storage-path>/dump`, so
665	//     platform archives have no `volid` at all: they cannot appear in the
666	//     `/storage/backup/content` listing this function iterates, and there is no
667	//     volid string that `DELETE /storage/backup/content/<volid>` could resolve to
668	//     them. Not "filtered out" — not addressable.
669	//  2. CHOKEPOINT. `deleteBackup` is the only function in the repo that issues a
670	//     storage-content DELETE (whole-repo grep: this file plus its single caller in
671	//     worker/index.ts). It re-derives protection for every volid immediately
672	//     before deleting and refuses on any of: the PVE `protected` attribute, the
673	//     platform notes marker, or the protection registry — and it fails CLOSED if
674	//     it cannot determine the answer.
675	//  3. MARKER + REGISTRY. If the platform job is ever pointed back at a shared PVE
676	//     storage (`NXEON_VM_BACKUP_STORAGE=backup`), it stamps each archive with
677	//     `--notes-template` carrying PLATFORM_BACKUP_MARKER and appends the volid to
678	//     PROTECTED_REGISTRY. Both are honoured below, which also covers the archives
679	//     already sitting in /tank/backup/dump from the 2026-07-26 04:31 run, written
680	//     before layer 1 existed.
681	
682	/** Where the platform's own whole-system vzdump archives live — outside every PVE storage. */
683	export const PLATFORM_BACKUP_DIR = process.env.NXEON_PLATFORM_BACKUP_DIR ?? "/tank/backup/platform";
684	
685	/**
686	 * Stamped into the vzdump notes of platform archives (see `--notes-template` in
687	 * scripts/backup-vms.sh). Customer retention must never delete an archive whose
688	 * notes contain this string.
689	 */
690	export const PLATFORM_BACKUP_MARKER = "NXEON-PLATFORM-BACKUP";
691	
692	/**
693	 * One volid per line. Maintained by scripts/backup-vms.sh; also seeded with any
694	 * pre-existing platform archives that were written into the shared storage before
695	 * the dumpdir split. Anything listed here is undeletable through this module.
696	 */
697	const PROTECTED_REGISTRY = `${PLATFORM_BACKUP_DIR}/PROTECTED-VOLIDS`;
698	
699	/**
700	 * Read the protection registry.
701	 *
702	 * Returns `null` when the registry exists but could not be read. Callers MUST
703	 * treat `null` as "protection state unknown" and refuse to delete: a transient
704	 * EIO on this file must not be the thing that lets a customer's prune wipe the
705	 * platform's recovery set. A registry that simply does not exist yet (fresh
706	 * install, platform job has never run) is a legitimate empty set — layer 1 means
707	 * there is nothing in the shared storage to protect in that case anyway.
708	 */
709	async function protectedVolids(): Promise<Set<string> | null> {
710	  const { readFile } = await import("node:fs/promises");
711	  try {
712	    const raw = await readFile(PROTECTED_REGISTRY, "utf8");
713	    return new Set(
714	      raw.split("\n").map((l) => l.trim()).filter((l) => l.length > 0 && !l.startsWith("#"))
715	    );
716	  } catch (e: any) {
717	    if (e?.code === "ENOENT") return new Set();
718	    console.error(`[proxmox] protection registry ${PROTECTED_REGISTRY} unreadable — refusing to prune`, e);
719	    return null;
720	  }
721	}
722	
723	/** Shape of one entry in `/nodes/<node>/storage/<sid>/content`. */
724	/**
725	 * Every backup archive the `backup` storage holds for one VMID, read through a
726	 * node-scoped client. This is the READ-BACK that `backupCreate` uses to prove an
727	 * archive actually exists: the vzdump task's exit status says the task ran, not
728	 * that a file landed. See worker/backup-schedule.ts (`freshBackupProof`) and
729	 * incident H4.
730	 */
731	export async function listBackupsOn(client: any, vmid: number): Promise<StorageBackupEntry[]> {
732	  const content: StorageBackupEntry[] = await client.get(
733	    `/nodes/${client.node}/storage/backup/content`,
734	    { content: "backup" }
735	  );
736	  return content.filter((b) => b.vmid === vmid && typeof b.volid === "string");
737	}
738	
739	export type StorageBackupEntry = {
740	  volid?: string;
741	  vmid?: number;
742	  ctime?: number;
743	  size?: number;
744	  notes?: string;
745	  protected?: boolean | number;
746	};
747	
748	/**
749	 * Is this archive one of the platform's own (i.e. never customer-prunable)?
750	 * Any single signal is enough — they are deliberately redundant.
751	 */
752	export function isPlatformArchive(b: StorageBackupEntry, registry: Set<string>): boolean {
753	  if (b.protected) return true;
754	  if (typeof b.notes === "string" && b.notes.includes(PLATFORM_BACKUP_MARKER)) return true;
755	  if (typeof b.volid === "string" && registry.has(b.volid)) return true;
756	  return false;
757	}
758	
759	/**
760	 * Delete one backup archive by its Proxmox volume id. `client` = the node's pve client.
761	 *
762	 * This is the ONLY storage-content DELETE in the codebase, so it is where the
763	 * "a customer can never delete a platform archive" invariant is enforced rather
764	 * than merely intended. It re-checks protection against the live hypervisor for
765	 * the exact volid being deleted — a caller that passed a stale or hand-crafted
766	 * volid cannot slip past it. Every uncertain outcome throws.
767	 */
768	export async function deleteBackup(client: any, volid: string): Promise<void> {
769	  // Only `<storage>:backup/<basename>` volids are deletable here. Rejecting
770	  // anything else keeps a malformed or path-traversing volid from ever reaching
771	  // the API, and keeps this function honest about what it operates on.
772	  const m = /^([A-Za-z0-9._-]+):backup\/([^/]+)$/.exec(volid);
773	  if (!m) throw new Error(`refusing to delete: '${volid}' is not a <storage>:backup/<file> volid`);
774	
775	  const registry = await protectedVolids();
776	  if (registry === null) {
777	    throw new Error(`refusing to delete ${volid}: platform protection registry unreadable`);
778	  }
779	  if (registry.has(volid)) {
780	    throw new Error(`refusing to delete ${volid}: listed in the platform protection registry`);
781	  }
782	
783	  // Ask the hypervisor about this exact volume. `notes` and `protected` are both
784	  // returned by the content-info endpoint (PVE::API2::Storage::Content). A failure
785	  // here means we do not know whether this is a platform archive, so we stop.
786	  let info: any;
787	  try {
788	    info = await client.get(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
789	  } catch (e) {
790	    throw new Error(`refusing to delete ${volid}: could not read its attributes (${e})`);
791	  }
792	  if (isPlatformArchive({ volid, notes: info?.notes, protected: info?.protected }, registry)) {
793	    throw new Error(`refusing to delete ${volid}: it is a platform (host-level) backup`);
794	  }
795	
796	  await client.del(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
797	}
798	
799	/**
800	 * Retention for ONE CUSTOMER SERVER: keep only the newest `keep` archives that
801	 * belong to that customer, deleting the older ones (best-effort per file, oldest
802	 * first). Runs after every successful customer backup, and from the standalone
803	 * sweep in worker/backup-schedule.ts. Returns how many were deleted.
804	 *
805	 * Platform archives are excluded from the delete set AND from the retention
806	 * count. Counting them would be its own bug: with keep = 2, three platform
807	 * archives of a vmid would make every customer archive "older than the newest
808	 * two" and delete all of the customer's backups instead.
809	 */
810	export async function pruneBackups(client: any, vmid: number, keep: number): Promise<number> {
811	  // `keep` decides how many of a customer's restore points survive, so it is
812	  // validated rather than trusted. `mine.slice(Math.max(0, keep))` looks safe and
813	  // is not: Math.max(0, NaN) is NaN, Array.slice(NaN) coerces to slice(0), and the
814	  // delete set silently becomes EVERY backup the customer has. A keep that arrived
815	  // as undefined, "" or a bad Settings parse would wipe the lot with no error on
816	  // the way past. Fail closed instead — an over-retained archive costs disk, a
817	  // missing one costs the customer their only restore point.
818	  if (!Number.isInteger(keep) || keep < 1) {
819	    throw new Error(
820	      `pruneBackups: refusing to prune vmid ${vmid} with keep='${keep}' — ` +
821	        `retention must be a whole number of at least 1.`
822	    );
823	  }
824	
825	  const registry = await protectedVolids();
826	  if (registry === null) {
827	    // Fail closed: no retention this pass. Archives accumulating for one cycle is
828	    // recoverable; deleting the platform's only copy of a VM is not.
829	    console.error(`[proxmox] pruneBackups: protection state unknown, skipping prune for vmid ${vmid}`);
830	    return 0;
831	  }
832	
833	  const forVmid = await listBackupsOn(client, vmid);
834	  const shielded = forVmid.filter((b) => isPlatformArchive(b, registry));
835	  const mine = forVmid
836	    .filter((b) => !isPlatformArchive(b, registry))
837	    .sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
838	
839	  if (shielded.length > 0) {
840	    console.log(
841	      `[proxmox] pruneBackups: vmid ${vmid} — ${shielded.length} platform archive(s) excluded from retention`
842	    );
843	  }
844	
845	  const toDelete = mine.slice(Math.max(0, keep));
846	  let deleted = 0;
847	  for (const b of toDelete) {
848	    try {
849	      await deleteBackup(client, b.volid!);
850	      deleted++;
851	    } catch (e) {
852	      console.error(`[proxmox] pruneBackups: failed to delete ${b.volid}`, e);
853	    }
854	  }
855	  return deleted;
856	}
