1	"use client";
2	
3	import { useState, useTransition } from "react";
4	import { setBackupSchedule } from "@/lib/actions-server-lifecycle";
5	
6	const INTERVALS: { hours: number; label: string }[] = [
7	  { hours: 12, label: "Every 12 hours" },
8	  { hours: 24, label: "Daily" },
9	  { hours: 48, label: "Every 2 days" },
10	  { hours: 72, label: "Every 3 days" },
11	  { hours: 168, label: "Weekly" },
12	];
13	
14	/** "No proven restore point" must not read like ordinary grey helper text. */
15	const SEVERITY: Record<string, string> = {
16	  off: "text-slate-500",
17	  ok: "text-slate-500",
18	  pending: "text-slate-400",
19	  never: "text-amber-400",
20	  stale: "text-amber-400",
21	  failing: "text-red-400",
22	};
23	
24	/**
25	 * The schedule panel never states an outcome the engine did not prove.
26	 *
27	 * It used to render "Last automatic backup: <lastAutoBackup>" from a column the
28	 * SWEEP stamped at ENQUEUE time — so a server whose vzdump failed every night
29	 * still showed a fresh timestamp, indefinitely (incident H4). `health` is now
30	 * computed server-side by `backupScheduleHealth` from a column that is written
31	 * only after an archive is observed in storage, and it renders absence loudly
32	 * instead of hiding it behind a date.
33	 */
34	export function BackupSchedule({
35	  serverId,
36	  autoBackup,
37	  backupIntervalHours,
38	  health,
39	}: {
40	  serverId: string;
41	  autoBackup: boolean;
42	  backupIntervalHours: number | null;
43	  /** Server-computed proof state — see `backupScheduleHealth` in worker/backup-schedule.ts */
44	  health: { state: "off" | "ok" | "pending" | "never" | "stale" | "failing"; detail: string };
45	}) {
46	  const [enabled, setEnabled] = useState(autoBackup);
47	  const [interval, setInterval] = useState<number>(backupIntervalHours ?? 24);
48	  const [error, setError] = useState<string | null>(null);
49	  const [saved, setSaved] = useState(false);
50	  const [pending, start] = useTransition();
51	
52	  function save(nextEnabled: boolean, nextInterval: number) {
53	    start(async () => {
54	      setError(null);
55	      setSaved(false);
56	      const res = await setBackupSchedule(serverId, nextEnabled, nextInterval);
57	      if (res?.error) {
58	        setError(res.error);
59	        setEnabled(autoBackup); // revert toggle to server truth on failure
60	      } else {
61	        setSaved(true);
62	      }
63	    });
64	  }
65	
66	  function flip() {
67	    const next = !enabled;
68	    setEnabled(next); // optimistic
69	    save(next, interval);
70	  }
71	
72	  return (
73	    <div className="card">
74	      <div className="flex flex-wrap items-start justify-between gap-4">
75	        <div>
76	          <h2 className="font-semibold">Scheduled backups</h2>
77	          <p className="mt-1 max-w-md text-sm text-slate-400">
78	            Automatically create a full-image backup on a recurring schedule. Backups land on the
79	            separate backup pool — independent from your server&apos;s NVMe storage.
80	          </p>
81	        </div>
82	        <button
83	          type="button"
84	          role="switch"
85	          aria-checked={enabled}
86	          disabled={pending}
87	          onClick={flip}
88	          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
89	            enabled ? "bg-brand-500" : "bg-white/15"
90	          } ${pending ? "opacity-60" : ""}`}
91	        >
92	          <span
93	            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
94	              enabled ? "translate-x-5" : "translate-x-0.5"
95	            }`}
96	          />
97	        </button>
98	      </div>
99	
100	      {enabled && (
101	        <>
102	          <div className="divider" />
103	          <label className="block text-sm">
104	            <span className="mb-1.5 block font-medium">Backup frequency</span>
105	            <select
106	              className="input"
107	              value={interval}
108	              disabled={pending}
109	              onChange={(e) => {
110	                const v = Number(e.target.value);
111	                setInterval(v);
112	                save(true, v);
113	              }}
114	            >
115	              {INTERVALS.map((i) => (
116	                <option key={i.hours} value={i.hours}>
117	                  {i.label}
118	                </option>
119	              ))}
120	            </select>
121	          </label>
122	          {/* `health` reflects SERVER truth. If the customer has just flipped the
123	              toggle on, the server still says "off" — say what is actually true
124	              in that moment rather than reusing a state that predates the click. */}
125	          <p className={`mt-3 text-xs ${SEVERITY[autoBackup ? health.state : "off"]}`}>
126	            {autoBackup
127	              ? health.detail
128	              : "Scheduled — the first backup is queued by the next sweep, and this panel will only report one once it has been verified in storage."}
129	          </p>
130	        </>
131	      )}
132	
133	      {error && <p className="mt-3 text-sm text-red-400">{error}</p>}
134	      {saved && !error && !pending && (
135	        <p className="mt-3 text-sm text-emerald-400">Backup schedule saved.</p>
136	      )}
137	    </div>
138	  );
139	}
