/**
 * Pure, dependency-free logic for the admin fleet-wide Backups view.
 *
 * No I/O, no Prisma, no Proxmox, no clock (every entry point that needs "now"
 * takes it as an argument). Factored out of the server component and the
 * `"use server"` action module so the archive→owner join and the
 * "servers with no recent backup" risk computation can be unit-tested as pure
 * functions (test/backups-admin.test.ts). See lib/actions-backups-admin.ts for
 * the I/O that feeds these.
 *
 * The join is the platform's oldest backup footgun (see lib/proxmox.ts
 * `pickProvisionVmid`): backups are keyed by the vmid embedded in their volid,
 * and a Server row is keyed by the same vmid, so an archive whose vmid has no
 * live owner is an ORPHAN — a previous tenant's data still on disk — and must be
 * shown as such, never silently attributed to whoever holds that vmid now.
 */

/** One row of a Proxmox `backup` storage content listing (the fields we read). */
export type RawArchive = {
  volid?: string;
  vmid?: number;
  ctime?: number;
  size?: number;
};

/** The subset of a Server row the join needs. `vmid` is required (non-null). */
export type ServerLite = {
  id: string;
  vmid: number;
  hostname: string;
  email: string;
};

/** A raw archive tagged with the node whose `backup` storage returned it. */
export type NodeArchive = { nodeLabel: string; raw: RawArchive };

/** An archive joined to its owning Server, or flagged as an orphan. */
export type JoinedArchive = {
  volid: string;
  vmid: number | null;
  ctime: number | null;
  size: number | null;
  nodeLabel: string;
  /** The owning server, or null when no live Server holds this vmid. */
  server: ServerLite | null;
  /** True when no live Server owns this archive's vmid — previous-tenant data. */
  orphan: boolean;
};

/**
 * Extract the vmid a vzdump volid names, e.g.
 *   `backup:backup/vzdump-qemu-102-2026_07_26-04_31_00.vma.zst` -> 102
 * Returns null when the string is not a recognisable vzdump volid. This is a
 * defence-in-depth check for restore: the archive's `vmid` field is the
 * authority, but the volid a client hands back must ALSO name the target vmid,
 * so a recycled or hand-crafted volid can never slip a stranger's archive past
 * the owner check.
 */
export function vmidFromVolid(volid: string | null | undefined): number | null {
  if (typeof volid !== "string") return null;
  const m = /vzdump-[a-z]+-(\d+)-/i.exec(volid);
  if (!m) return null;
  const n = Number(m[1]);
  return Number.isInteger(n) ? n : null;
}

/** The vmid an archive belongs to: prefer the storage field, fall back to the volid. */
export function resolveArchiveVmid(raw: RawArchive): number | null {
  if (typeof raw.vmid === "number" && Number.isInteger(raw.vmid)) return raw.vmid;
  return vmidFromVolid(raw.volid);
}

/**
 * Join every enumerated archive to the Server that owns its vmid. Archives with
 * no addressable volid are dropped (there is nothing to act on); archives whose
 * vmid has no live Server are KEPT and flagged `orphan` so the UI can surface
 * previous-tenant data rather than hide it.
 */
export function joinArchives(
  entries: readonly NodeArchive[],
  servers: readonly ServerLite[]
): JoinedArchive[] {
  const byVmid = new Map<number, ServerLite>();
  for (const s of servers) byVmid.set(s.vmid, s);

  const out: JoinedArchive[] = [];
  for (const { nodeLabel, raw } of entries) {
    if (typeof raw.volid !== "string") continue; // nothing addressable to restore
    const vmid = resolveArchiveVmid(raw);
    const server = vmid !== null ? byVmid.get(vmid) ?? null : null;
    out.push({
      volid: raw.volid,
      vmid,
      ctime: typeof raw.ctime === "number" ? raw.ctime : null,
      size: typeof raw.size === "number" ? raw.size : null,
      nodeLabel,
      server,
      orphan: server === null,
    });
  }
  return out;
}

export type BackupTotals = {
  totalArchives: number;
  totalSizeBytes: number;
  /** Unix seconds of the newest/oldest archive, or null when there are none. */
  newestCtime: number | null;
  oldestCtime: number | null;
  orphanCount: number;
};

/** Roll a set of joined archives up into the summary strip's numbers. */
export function summarizeArchives(joined: readonly JoinedArchive[]): BackupTotals {
  let totalSizeBytes = 0;
  let newest: number | null = null;
  let oldest: number | null = null;
  let orphanCount = 0;
  for (const a of joined) {
    if (typeof a.size === "number") totalSizeBytes += a.size;
    if (a.ctime !== null) {
      if (newest === null || a.ctime > newest) newest = a.ctime;
      if (oldest === null || a.ctime < oldest) oldest = a.ctime;
    }
    if (a.orphan) orphanCount++;
  }
  return {
    totalArchives: joined.length,
    totalSizeBytes,
    newestCtime: newest,
    oldestCtime: oldest,
    orphanCount,
  };
}

export type AtRiskReason = "none" | "stale";
export type AtRiskServer = ServerLite & {
  /** "none" = no archive at all; "stale" = newest archive older than the window. */
  reason: AtRiskReason;
  /** Unix seconds of the newest archive we could see for this server, or null. */
  newestCtime: number | null;
};

/**
 * Servers whose most recent RESTORE POINT is missing or too old — the real risk
 * signal at the top of the page. Computed from the archives actually observed in
 * storage (so a manual backup counts too, not just the auto schedule), against
 * a single freshness window.
 *
 * IMPORTANT (honesty): this reads only the archives it was given. If a node
 * failed to enumerate, its archives are absent and its servers would look
 * at-risk here — so the caller MUST caveat this list whenever a node could not
 * be read, rather than presenting "no recent backup" as fact. See the page.
 */
export function serversWithNoRecentBackup(opts: {
  servers: readonly ServerLite[];
  joined: readonly JoinedArchive[];
  now: number;
  staleMs: number;
}): AtRiskServer[] {
  const newestByServer = new Map<string, number>();
  for (const a of opts.joined) {
    if (!a.server || a.ctime === null) continue;
    const cur = newestByServer.get(a.server.id);
    if (cur === undefined || a.ctime > cur) newestByServer.set(a.server.id, a.ctime);
  }

  const out: AtRiskServer[] = [];
  for (const s of opts.servers) {
    const newest = newestByServer.get(s.id);
    if (newest === undefined) {
      out.push({ ...s, reason: "none", newestCtime: null });
    } else if (opts.now - newest * 1000 > opts.staleMs) {
      out.push({ ...s, reason: "stale", newestCtime: newest });
    }
  }
  return out;
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { nodeTargets, BACKUP_STALE_MS } from "./monitoring";
import { pveFor, listBackups, listBackupsOn } from "./proxmox";
import { backupScheduleHealth, type BackupHealth } from "./backup-verify";
import {
  joinArchives,
  summarizeArchives,
  serversWithNoRecentBackup,
  vmidFromVolid,
  type NodeArchive,
  type ServerLite,
  type JoinedArchive,
  type BackupTotals,
  type AtRiskServer,
} from "@/app/admin/backups/logic";

/**
 * ADMIN fleet-wide backup actions.
 *
 * `"use server"` means every export here is a network-reachable endpoint, so
 * each one re-checks `requireArea("fleet")` INSIDE the function — a dropped guard
 * on the restore action would be a cross-tenant data-DESTRUCTION hole, not just a
 * data leak. Backups are live-from-Proxmox (there is no Backup table): we
 * enumerate every node's `backup` storage and join each archive's vmid to a
 * Server row, exactly as the customer surface and the admin monitoring page do.
 *
 * HONESTY: a node that cannot be enumerated is reported as `reachable: false`,
 * never dropped. A silently missing node reads as "these servers have no
 * backups", which at restore time is the most dangerous lie this page could tell.
 */

// ---------------------------------------------------------------------------
// Serializable view returned to the (client) admin table
// ---------------------------------------------------------------------------

/** Per-node enumeration outcome — honest about nodes we could not read. */
export type NodeEnum = { label: string; reachable: boolean; archiveCount: number };

/** Per-server backup-schedule health row (dates as ISO strings for the client). */
export type ServerScheduleRow = {
  id: string;
  vmid: number | null;
  hostname: string;
  email: string;
  nodeLabel: string | null;
  status: string;
  autoBackup: boolean;
  backupIntervalHours: number | null;
  lastAutoBackup: string | null;
  health: BackupHealth;
};

export type AdminBackupsView = {
  nodes: NodeEnum[];
  anyNodeUnreachable: boolean;
  archives: JoinedArchive[];
  summary: BackupTotals;
  atRisk: AtRiskServer[];
  servers: ServerScheduleRow[];
  staleMs: number;
};

/**
 * Enumerate every node's `backup` storage, join each archive to its owning
 * Server, and compute the summary + at-risk + per-server schedule health.
 */
export async function listAllBackups(): Promise<AdminBackupsView> {
  await requireArea("fleet");

  const [targets, servers] = await Promise.all([
    nodeTargets(),
    db.server.findMany({
      where: { vmid: { not: null } },
      select: {
        id: true,
        vmid: true,
        hostname: true,
        status: true,
        autoBackup: true,
        backupIntervalHours: true,
        lastAutoBackup: true,
        user: { select: { email: true } },
        node: { select: { name: true } },
      },
    }),
  ]);

  // Read each node's backup-storage content. This is the same read-only
  // `/storage/backup/content` call `listBackupsOn`/`backupSummary` make; we read
  // the FULL listing (no vmid filter) because orphan archives — whose vmid has no
  // Server — must be surfaced, and a vmid-filtered read can never see them.
  const nodes: NodeEnum[] = [];
  const entries: NodeArchive[] = [];
  let anyNodeUnreachable = false;
  for (const t of targets) {
    try {
      const items: any[] = await t.get(`/nodes/${t.pveNode}/storage/backup/content`, {
        content: "backup",
      });
      let count = 0;
      for (const raw of items ?? []) {
        if (typeof raw?.volid !== "string") continue;
        entries.push({
          nodeLabel: t.label,
          raw: {
            volid: raw.volid,
            vmid: typeof raw.vmid === "number" ? raw.vmid : undefined,
            ctime: typeof raw.ctime === "number" ? raw.ctime : undefined,
            size: typeof raw.size === "number" ? raw.size : undefined,
          },
        });
        count++;
      }
      nodes.push({ label: t.label, reachable: true, archiveCount: count });
    } catch {
      nodes.push({ label: t.label, reachable: false, archiveCount: 0 });
      anyNodeUnreachable = true;
    }
  }

  const serverLites: ServerLite[] = servers.map((s) => ({
    id: s.id,
    vmid: s.vmid as number,
    hostname: s.hostname,
    email: s.user?.email ?? "—",
  }));

  const archives = joinArchives(entries, serverLites).sort(
    (a, b) => (b.ctime ?? 0) - (a.ctime ?? 0)
  );
  const summary = summarizeArchives(archives);

  const now = Date.now();
  const atRisk = serversWithNoRecentBackup({
    servers: serverLites,
    joined: archives,
    now,
    staleMs: BACKUP_STALE_MS,
  });

  // Per-server schedule health uses the DB proof timestamp + the last CREATE
  // attempt, exactly like the customer server-detail page.
  const ids = servers.map((s) => s.id);
  const attempts = ids.length
    ? await db.job.findMany({
        where: { type: "BACKUP_CREATE", serverId: { in: ids } },
        orderBy: { createdAt: "desc" },
        select: { serverId: true, createdAt: true, status: true },
      })
    : [];
  const lastAttempt = new Map<string, { at: Date; status: string }>();
  for (const j of attempts) {
    if (j.serverId && !lastAttempt.has(j.serverId)) {
      lastAttempt.set(j.serverId, { at: j.createdAt, status: j.status });
    }
  }

  const serverRows: ServerScheduleRow[] = servers.map((s) => ({
    id: s.id,
    vmid: s.vmid,
    hostname: s.hostname,
    email: s.user?.email ?? "—",
    nodeLabel: s.node?.name ?? null,
    status: s.status,
    autoBackup: s.autoBackup,
    backupIntervalHours: s.backupIntervalHours,
    lastAutoBackup: s.lastAutoBackup ? s.lastAutoBackup.toISOString() : null,
    health: backupScheduleHealth({
      now,
      autoBackup: s.autoBackup,
      intervalHours: s.backupIntervalHours,
      lastVerifiedAt: s.lastAutoBackup,
      lastAttempt: lastAttempt.get(s.id) ?? null,
    }),
  }));

  return {
    nodes,
    anyNodeUnreachable,
    archives,
    summary,
    atRisk,
    servers: serverRows,
    staleMs: BACKUP_STALE_MS,
  };
}

// ---------------------------------------------------------------------------
// Destructive: restore a live VM from one of ITS OWN archives
// ---------------------------------------------------------------------------

/**
 * Enqueue a BACKUP_RESTORE for `volid` against `serverId`.
 *
 * The volid is NEVER trusted: it must (1) name this server's vmid structurally
 * and (2) actually be present in the live listing of that vmid's archives on the
 * server's own node. A recycled or mismatched volid restoring a stranger's root
 * filesystem onto this VM — handing over their databases, secrets and /etc/shadow
 * — is precisely the class of bug documented in lib/proxmox.ts `pickProvisionVmid`.
 */
export async function adminRequestRestore(
  serverId: string,
  volid: string
): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireArea("fleet");

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { node: true },
  });
  if (!server) return { error: "Server not found." };
  if (!server.vmid) return { error: "Server has no VM yet." };
  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to restore a backup." };
  }

  // (1) Structural: the volid must name THIS server's vmid.
  const named = vmidFromVolid(volid);
  if (named === null || named !== server.vmid) {
    return { error: "That backup does not belong to this server." };
  }

  // (2) Authoritative: the archive must exist for this vmid, read from the
  // server's own node (vmids can collide across nodes, so the primary is wrong
  // for a server pinned elsewhere).
  let owned: { volid?: string }[];
  try {
    if (server.node) {
      const client = pveFor({
        apiUrl: server.node.apiUrl,
        pveNode: server.node.pveNode,
        tokenId: server.node.tokenId,
        tokenSecret: server.node.tokenSecret,
      });
      owned = await listBackupsOn(client, server.vmid);
    } else {
      owned = (await listBackups(server.vmid)) as { volid?: string }[];
    }
  } catch {
    return { error: "Could not verify the backup — the hypervisor is briefly unavailable." };
  }
  if (!owned.some((b) => b.volid === volid)) {
    return { error: "That backup was not found for this server." };
  }

  // No concurrent job — the worker is serial and restore overwrites the disk.
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) {
    return { error: "Another operation is already in progress on this server." };
  }

  await db.job.create({ data: { type: "BACKUP_RESTORE", serverId, payload: { volid } } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "admin.backup_restore", detail: `${serverId} ${volid}` },
  });
  revalidatePath("/admin/backups");
  return { ok: true };
}

/** Enqueue a BACKUP_CREATE for `serverId` on the customer's behalf. */
export async function adminCreateBackup(
  serverId: string
): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireArea("fleet");

  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) return { error: "Server not found." };
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped." };
  }

  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) {
    return { error: "Another operation is already in progress on this server." };
  }

  await db.job.create({ data: { type: "BACKUP_CREATE", serverId } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "admin.backup_create", detail: serverId },
  });
  revalidatePath("/admin/backups");
  return { ok: true };
}

export type AdminBackupJob = {
  id: string;
  type: "BACKUP_CREATE" | "BACKUP_RESTORE";
  status: "QUEUED" | "RUNNING" | "DONE" | "FAILED";
  progress: number;
  step: string | null;
  error: string | null;
  createdAt: string;
};

/** The most recent backup/restore job for a server, so the admin UI can poll progress. */
export async function adminGetBackupJob(serverId: string): Promise<AdminBackupJob | null> {
  await requireArea("fleet");
  const job = await db.job.findFirst({
    where: { serverId, type: { in: ["BACKUP_CREATE", "BACKUP_RESTORE"] } },
    orderBy: { createdAt: "desc" },
    select: {
      id: true,
      type: true,
      status: true,
      progress: true,
      step: true,
      error: true,
      createdAt: true,
    },
  });
  if (!job) return null;
  return {
    id: job.id,
    type: job.type as AdminBackupJob["type"],
    status: job.status as AdminBackupJob["status"],
    progress: job.progress,
    step: job.step,
    error: job.error,
    createdAt: job.createdAt.toISOString(),
  };
}

