function fmtWhen(ctime: number | null): string {
  if (!ctime) return "—";
  return new Date(ctime * 1000).toISOString().slice(0, 16).replace("T", " ") + " UTC";
}
function ageDays(ctime: number | null): string {
  if (!ctime) return "—";
  const d = Math.floor((Date.now() - ctime * 1000) / 86_400_000);
  if (d <= 0) {
    const h = Math.floor((Date.now() - ctime * 1000) / 3_600_000);
    return h <= 0 ? "just now" : `${h}h`;
  }
  return `${d}d`;
}
function baseName(volid: string): string {
  return volid.split("/").pop() ?? volid;
}

