}

function ArchiveTable({ view }: { view: AdminBackupsView }) {
  const router = useRouter();
  const [q, setQ] = useState("");
  const [nodeFilter, setNodeFilter] = useState("");
  const [orphansOnly, setOrphansOnly] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pendingVolid, setPendingVolid] = useState<string | null>(null);

  const nodeNames = useMemo(
    () => Array.from(new Set(view.archives.map((a) => a.nodeLabel))).sort(),
    [view.archives]
  );

  const rows = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return view.archives.filter((a) => {
      if (orphansOnly && !a.orphan) return false;
      if (nodeFilter && a.nodeLabel !== nodeFilter) return false;
      if (!needle) return true;
      const hay = [
        a.server?.hostname,
        a.server?.email,
        a.vmid !== null ? String(a.vmid) : "",
        baseName(a.volid),
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return hay.includes(needle);
    });
  }, [view.archives, q, nodeFilter, orphansOnly]);

  function restore(a: (typeof view.archives)[number]) {
    if (!a.server) return; // orphans have no owner to restore onto
    const ok = window.confirm(
      `RESTORE — this OVERWRITES the live VM.\n\n` +
        `Server: ${a.server.hostname} (${a.server.email})\n` +
        `VMID: ${a.vmid}\n` +
        `Archive: ${baseName(a.volid)}\n(${fmtWhen(a.ctime)})\n\n` +
        `The server is stopped, its disk is replaced with this archive, then it is ` +
        `started again. EVERY change made since this backup is permanently lost.\n\n` +
        `Type OK to enqueue the restore.`
    );
    if (!ok) return;
    setError(null);
    setPendingVolid(a.volid);
    adminRequestRestore(a.server.id, a.volid).then((res) => {
      setPendingVolid(null);
      if (res?.error) setError(res.error);
      else router.refresh();
    });
  }

  return (
    <div className="card p-0">
      <div className="flex flex-wrap items-center gap-3 border-b border-white/[0.06] px-4 py-3">
        <input
          className="input max-w-xs py-1.5"
          placeholder="Filter by host, email, vmid, archive…"
          value={q}
          onChange={(e) => setQ(e.target.value)}
        />
        <select
          className="input max-w-[10rem] py-1.5"
          value={nodeFilter}
          onChange={(e) => setNodeFilter(e.target.value)}
        >
          <option value="">All nodes</option>
          {nodeNames.map((n) => (
            <option key={n} value={n}>
              {n}
            </option>
          ))}
        </select>
        <label className="flex items-center gap-2 text-xs text-slate-400">
          <input
            type="checkbox"
            checked={orphansOnly}
            onChange={(e) => setOrphansOnly(e.target.checked)}
          />
          Orphans only
        </label>
        <span className="ml-auto text-xs text-slate-500">
          {rows.length} of {view.archives.length} shown
        </span>
      </div>

      {error && <p className="px-4 pt-3 text-sm text-red-400">{error}</p>}

      {rows.length === 0 ? (
        <p className="px-4 py-10 text-center text-sm text-slate-500">
          No archives match these filters.
        </p>
      ) : (
        <div className="overflow-x-auto">
          <table className="table-shell">
            <thead>
              <tr>
                <th>Archive</th>
                <th>Owner</th>
                <th>VMID</th>
                <th>Node</th>
                <th>Age</th>
                <th className="text-right">Size</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((a) => (
                <tr key={`${a.nodeLabel}:${a.volid}`}>
                  <td className="font-mono text-xs" title={fmtWhen(a.ctime)}>
                    {baseName(a.volid)}
                  </td>
                  <td className="text-xs">
                    {a.server ? (
                      <Link
                        href={`/admin/servers/${a.server.id}`}
                        className="hover:text-brand-300"
                      >
                        <span className="font-medium">{a.server.hostname}</span>
                        <span className="block text-slate-500">{a.server.email}</span>
                      </Link>
                    ) : (
                      <Badge tone="amber">orphan — no live owner</Badge>
                    )}
                  </td>
                  <td className="font-mono text-xs text-slate-400">{a.vmid ?? "—"}</td>
                  <td className="text-xs text-slate-400">{a.nodeLabel}</td>
                  <td className="text-xs text-slate-400">{ageDays(a.ctime)}</td>
                  <td className="text-right text-xs text-slate-400">{fmtBytes(a.size ?? 0)}</td>
                  <td className="text-right">
                    <button
                      className="btn-danger px-3 py-1 text-xs"
                      disabled={!a.server || pendingVolid === a.volid}
                      title={a.server ? "Overwrites the live VM" : "Orphan archive — no owner to restore onto"}
                      onClick={() => restore(a)}
                    >
                      {pendingVolid === a.volid ? "Queueing…" : "Restore"}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      <p className="px-4 py-3 text-xs text-slate-500">
        Restore overwrites the live disk. Orphan archives (no live server owns their vmid) cannot be
        restored from here — they are previous-tenant data flagged for review.
      </p>
    </div>
  );
}

