const POLL_MS = 2500;

function CreateBackupButton({ serverId, disabled }: { serverId: string; disabled?: boolean }) {
  const router = useRouter();
  const [job, setJob] = useState<AdminBackupJob | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [queueing, setQueueing] = useState(false);
  const lastStatus = useRef<string | null>(null);

  const fetchJob = useCallback(async () => {
    try {
      const j = await adminGetBackupJob(serverId);
      if (j && lastStatus.current && lastStatus.current !== j.status && j.status === "DONE") {
        router.refresh();
      }
      if (j) lastStatus.current = j.status;
      setJob(j);
    } catch {
      /* transient — keep last state */
    }
  }, [serverId, router]);

  const inFlight = !!job && (job.status === "QUEUED" || job.status === "RUNNING");

  useEffect(() => {
    if (!inFlight) return;
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout>;
    async function loop() {
      if (cancelled) return;
      await fetchJob();
      if (!cancelled) timer = setTimeout(loop, POLL_MS);
    }
    loop();
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [inFlight, fetchJob]);

  return (
    <div className="flex flex-col items-end gap-1">
      <button
        className="btn-secondary px-3 py-1 text-xs"
        disabled={disabled || queueing || inFlight}
        onClick={async () => {
          setError(null);
          setQueueing(true);
          const res = await adminCreateBackup(serverId);
          setQueueing(false);
          if (res?.error) setError(res.error);
          else fetchJob();
        }}
      >
        {queueing
          ? "Queueing…"
          : inFlight
            ? `${job?.type === "BACKUP_RESTORE" ? "Restore" : "Backup"} ${job?.progress ?? 0}%`
            : "Create"}
      </button>
      {error && <span className="text-[11px] text-red-400">{error}</span>}
      {inFlight && job?.step && <span className="text-[11px] text-slate-500">{job.step}</span>}
    </div>
  );
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";
import {
  vmidFromVolid,
  resolveArchiveVmid,
  joinArchives,
  summarizeArchives,
  serversWithNoRecentBackup,
  type NodeArchive,
  type ServerLite,
} from "../app/admin/backups/logic.ts";

/**
 * The admin fleet Backups surface. Two kinds of test:
 *
 *  1. PURE LOGIC — the archive→owner vmid-join (including orphan detection) and
 *     the "servers with no recent backup" risk computation, exercised as the pure
 *     functions they were factored into.
 *  2. SOURCE TRIPWIRES — every export of the `"use server"` action module is a
 *     public endpoint, so each must authenticate (`requireArea("fleet")`) inside
 *     its body, and the destructive restore must RE-VALIDATE that the volid
 *     belongs to the target server's vmid (a mismatched/recycled volid restoring
 *     a stranger's archive onto a live VM is the class of bug this platform has
 *     been burned by). Source is comment/string-stripped so the assertion matches
 *     a CALL, not a mention in a doc-comment or error string.
 */

// ---------------------------------------------------------------------------
// 1. Pure logic
// ---------------------------------------------------------------------------

test("vmidFromVolid parses the vmid out of a vzdump volid", () => {
  assert.equal(
    vmidFromVolid("backup:backup/vzdump-qemu-102-2026_07_26-04_31_00.vma.zst"),
    102
  );
  assert.equal(vmidFromVolid("local:backup/vzdump-lxc-8000-2026_01_01-00_00_00.tar.zst"), 8000);
  assert.equal(vmidFromVolid("not-a-volid"), null);
  assert.equal(vmidFromVolid(undefined), null);
  assert.equal(vmidFromVolid(null), null);
});

test("resolveArchiveVmid prefers the storage vmid field, falls back to the volid", () => {
  assert.equal(resolveArchiveVmid({ vmid: 105, volid: "x:backup/vzdump-qemu-999-a.vma" }), 105);
  assert.equal(resolveArchiveVmid({ volid: "x:backup/vzdump-qemu-777-a.vma" }), 777);
  assert.equal(resolveArchiveVmid({ volid: "junk" }), null);
});

const SERVERS: ServerLite[] = [
  { id: "s-100", vmid: 100, hostname: "web-1", email: "alice@example.com" },
  { id: "s-101", vmid: 101, hostname: "db-1", email: "bob@example.com" },
];

test("joinArchives maps archives to owners and flags orphans", () => {
  const entries: NodeArchive[] = [
    { nodeLabel: "n1", raw: { volid: "backup:backup/vzdump-qemu-100-a.vma.zst", vmid: 100, ctime: 10, size: 5 } },
    // vmid only derivable from the volid — still joins.
    { nodeLabel: "n1", raw: { volid: "backup:backup/vzdump-qemu-101-b.vma.zst", ctime: 20, size: 7 } },
    // No live server owns vmid 999 — orphan (previous-tenant data).
    { nodeLabel: "n2", raw: { volid: "backup:backup/vzdump-qemu-999-c.vma.zst", vmid: 999, ctime: 30, size: 9 } },
    // No addressable volid — dropped entirely.
    { nodeLabel: "n2", raw: { vmid: 100, ctime: 40 } },
  ];
  const joined = joinArchives(entries, SERVERS);

  assert.equal(joined.length, 3, "the volid-less entry is dropped");

  const a100 = joined.find((j) => j.vmid === 100)!;
  assert.equal(a100.server?.id, "s-100");
  assert.equal(a100.orphan, false);
  assert.equal(a100.nodeLabel, "n1");

  const a101 = joined.find((j) => j.vmid === 101)!;
  assert.equal(a101.server?.hostname, "db-1", "joins via vmid parsed from the volid");
  assert.equal(a101.orphan, false);

  const orphan = joined.find((j) => j.vmid === 999)!;
  assert.equal(orphan.server, null);
  assert.equal(orphan.orphan, true);
});

test("summarizeArchives totals size, extremes and orphan count", () => {
  const joined = joinArchives(
    [
      { nodeLabel: "n1", raw: { volid: "b:backup/vzdump-qemu-100-a.vma", vmid: 100, ctime: 10, size: 5 } },
      { nodeLabel: "n1", raw: { volid: "b:backup/vzdump-qemu-999-b.vma", vmid: 999, ctime: 30, size: 9 } },
    ],
    SERVERS
  );
  const sum = summarizeArchives(joined);
  assert.equal(sum.totalArchives, 2);
  assert.equal(sum.totalSizeBytes, 14);
  assert.equal(sum.newestCtime, 30);
  assert.equal(sum.oldestCtime, 10);
  assert.equal(sum.orphanCount, 1);
});

test("serversWithNoRecentBackup flags missing AND stale restore points", () => {
  const now = 1_000_000_000_000; // fixed ms clock
  const staleMs = 48 * 60 * 60 * 1000;
  const recent = Math.floor((now - 1 * 60 * 60 * 1000) / 1000); // 1h ago (fresh)
  const old = Math.floor((now - 5 * 24 * 60 * 60 * 1000) / 1000); // 5d ago (stale)

  const joined = joinArchives(
    [
      { nodeLabel: "n1", raw: { volid: "b:backup/vzdump-qemu-100-a.vma", vmid: 100, ctime: recent, size: 5 } },
      { nodeLabel: "n1", raw: { volid: "b:backup/vzdump-qemu-101-b.vma", vmid: 101, ctime: old, size: 5 } },
    ],
    SERVERS
  );
  const withThird: ServerLite[] = [
    ...SERVERS,
    { id: "s-102", vmid: 102, hostname: "cache-1", email: "carol@example.com" },
  ];

  const risk = serversWithNoRecentBackup({ servers: withThird, joined, now, staleMs });
  const byId = new Map(risk.map((r) => [r.id, r]));

  assert.equal(byId.has("s-100"), false, "fresh archive => not at risk");
  assert.equal(byId.get("s-101")?.reason, "stale", "old archive => stale");
  assert.equal(byId.get("s-102")?.reason, "none", "no archive at all => none");
  assert.equal(risk.length, 2);
});

// ---------------------------------------------------------------------------
// 2. Source tripwires over the "use server" action module
// ---------------------------------------------------------------------------

const ACTION_FILE = join(import.meta.dirname, "..", "lib", "actions-backups-admin.ts");
const rawSource = readFileSync(ACTION_FILE, "utf8");
/** Comments removed but string LITERALS kept — for value assertions like requireArea("fleet"). */
const litSource = stripComments(rawSource);
/** Comments AND string contents removed — for CALL-shape assertions. */
const shapeSource = stripCommentsAndStrings(rawSource);

function exportedActions(src: string): string[] {
  return [...src.matchAll(/export\s+async\s+function\s+([A-Za-z0-9_$]+)\s*\(/g)].map((m) => m[1]);
}

/** Brace-matched body of an exported async function (skips the return-type generics). */
function bodyOf(src: string, name: string): string {
  const decl = new RegExp(`export\\s+async\\s+function\\s+${name}\\s*\\(`).exec(src);
  assert.ok(decl, `expected an exported action named ${name}`);
  let i = src.indexOf("(", decl.index);
  let parens = 0;
  let quote: string | null = null;
  for (; i < src.length; i++) {
    const c = src[i];
    if (quote) {
      if (c === "\\") i++;
      else if (c === quote) quote = null;
      continue;
    }
    if (c === '"' || c === "'" || c === "`") quote = c;
    else if (c === "(") parens++;
    else if (c === ")" && --parens === 0) break;
  }
  let angles = 0;
  for (i++; i < src.length; i++) {
    const c = src[i];
    if (c === "<") angles++;
    else if (c === ">") angles = Math.max(0, angles - 1);
    else if (c === "{" && angles === 0) break;
  }
  const start = i;
  let depth = 0;
  quote = null;
  for (; i < src.length; i++) {
    const c = src[i];
    if (quote) {
      if (c === "\\") i++;
      else if (c === quote) quote = null;
      continue;
    }
    if (c === '"' || c === "'" || c === "`") quote = c;
    else if (c === "{") depth++;
    else if (c === "}" && --depth === 0) return src.slice(start, i + 1);
  }
  assert.fail(`unbalanced body for ${name}`);
}

test("the module declares \"use server\" and exports the expected actions", () => {
  assert.ok(rawSource.includes('"use server"'), "must declare \"use server\"");
  const names = exportedActions(litSource);
  for (const expected of [
    "listAllBackups",
    "adminRequestRestore",
    "adminCreateBackup",
    "adminGetBackupJob",
  ]) {
    assert.ok(names.includes(expected), `expected an exported action ${expected}`);
  }
});

test("every exported action gates on requireArea(\"fleet\") inside its body", () => {
  const ungated: string[] = [];
  for (const name of exportedActions(litSource)) {
    // Literal-preserving source so the AREA value ("fleet") is checked, not just
    // that some requireArea() is present — a staff action must reach for the
    // right authority, never a weaker one.
    if (!bodyOf(litSource, name).includes('requireArea("fleet")')) ungated.push(name);
  }
  assert.deepEqual(
    ungated,
    [],
    "these admin backup endpoints are network-reachable without a fleet-area guard"
  );
});

test("adminRequestRestore re-validates the volid belongs to the target vmid", () => {
  const body = bodyOf(shapeSource, "adminRequestRestore");
  // Structural check: the volid must name this server's vmid.
  assert.match(
    body,
    /vmidFromVolid\(/,
    "restore must derive the vmid the volid names (structural ownership check)"
  );
  assert.match(
    body,
    /server\.vmid/,
    "restore must compare the parsed vmid against the target server's vmid"
  );
  // Authoritative check: the archive must actually exist for this vmid in the
  // live listing — never trust the client-supplied volid alone.
  assert.ok(
    /listBackupsOn\(/.test(body) || /listBackups\(/.test(body),
    "restore must confirm the volid against a LIVE backup listing"
  );
  assert.match(
    body,
    /\.some\(/,
    "restore must assert the volid is a member of the live listing"
  );
  // And only then does it enqueue the destructive job + write an audit trail.
  assert.match(body, /db\.job\.create\(/, "restore must enqueue the BACKUP_RESTORE job");
  assert.match(body, /db\.auditLog\.create\(/, "restore must write an AuditLog");
});

test("adminCreateBackup enqueues BACKUP_CREATE and writes an AuditLog", () => {
  const body = bodyOf(shapeSource, "adminCreateBackup");
  assert.match(body, /db\.job\.create\(/);
  assert.match(body, /db\.auditLog\.create\(/);
  // The BACKUP_CREATE job type is a value, so check it in the literal-preserving source.
  assert.match(bodyOf(litSource, "adminCreateBackup"), /BACKUP_CREATE/);
});

test("adminRequestRestore enqueues the BACKUP_RESTORE type with a volid payload", () => {
  const body = bodyOf(litSource, "adminRequestRestore");
  assert.match(body, /BACKUP_RESTORE/);
  assert.match(body, /payload:\s*\{\s*volid\s*\}/);
});
